"""Pinned Colab setup shared with the previously validated environments."""
SETUP = '\nfrom hypothesis_study import bounded_run, BudgetExceeded, write_json\n\ndef checked(command, label):\n    print(label, flush=True)\n    return bounded_run(command, OUTPUT / \'setup.log\', SOURCE, os.environ.copy(), DEADLINE)\n\ndef pinned_repository(url, directory, revision):\n    directory.parent.mkdir(parents=True, exist_ok=True)\n    if not directory.exists():\n        checked([\'git\', \'clone\', \'--quiet\', url, directory], f\'Cloning {directory.name}\')\n    # Read-only inspection; never overwrite a checkout with local edits.\n    status = subprocess.check_output([\'git\', \'-C\', str(directory), \'status\', \'--porcelain\'], text=True, timeout=10)\n    if status.strip():\n        raise RuntimeError(f\'Local edits found in {directory}; resolve them before changing its revision\')\n    checked([\'git\', \'-C\', directory, \'fetch\', \'--quiet\', \'origin\', revision], f\'Pinning {directory.name}\')\n    checked([\'git\', \'-C\', directory, \'checkout\', \'--quiet\', revision], f\'Checking {directory.name} revision\')\n\neval_probe = ("import torch,numpy,safetensors,sys,importlib;"\n              "assert torch.__version__.startswith(\'2.3.1\'),torch.__version__;"\n              "assert numpy.__version__==\'2.2.6\',numpy.__version__;"\n              "assert torch.cuda.is_available(),\'Select a GPU runtime\';"\n              "sys.path[:0]=[\'intervention\',\'.\'];importlib.import_module(\'models.vggt.run_pass\')")\nsam_probe = ("import torch,decord,pycocotools;from sam3.model_builder import build_sam3_image_model;"\n             "from sam3.model.sam3_image_processor import Sam3Processor;"\n             "assert torch.__version__.startswith(\'2.7.0\'),torch.__version__;"\n             "assert torch.cuda.is_available(),\'SAM requires a GPU\'")\n\ndef ready(python, probe, repo, revision):\n    if not python.exists() or not (repo / \'.git\').exists():\n        return False\n    head = subprocess.check_output([\'git\', \'-C\', str(repo), \'rev-parse\', \'HEAD\'], text=True, timeout=10).strip()\n    dirty = subprocess.check_output([\'git\', \'-C\', str(repo), \'status\', \'--porcelain\'], text=True, timeout=10).strip()\n    if head != revision or dirty:\n        return False\n    try:\n        checked([python, \'-c\', probe], f\'Checking existing {python.parent.parent.name} environment\')\n        return True\n    except BudgetExceeded:\n        raise\n    except RuntimeError:\n        return False\n\nvggt_revision = \'97bbde571faddde3ace3cfa7724a20448026c4c8\'\nsam_revision = \'11dec2936de97f2857c1f76b66d982d5a001155d\'\nvggt_dir, sam_dir = WORK / \'third_party/vggt\', WORK / \'third_party/sam3\'\ntry:\n    eval_ready = ready(EVAL_PY, eval_probe, vggt_dir, vggt_revision)\n    sam_ready = ready(SAM_PY, sam_probe, sam_dir, sam_revision)\n    if not (eval_ready and sam_ready):\n        checked([sys.executable, \'-m\', \'pip\', \'install\', \'-q\', \'uv\'], \'Preparing isolated environments\')\n        uv = [sys.executable, \'-m\', \'uv\']\n        if not eval_ready:\n            if not EVAL_PY.exists():\n                checked(uv + [\'venv\', \'--python\', \'3.12\', EVAL_PY.parent.parent], \'Creating VGGT environment\')\n            pip = uv + [\'pip\', \'install\', \'--python\', EVAL_PY]\n            checked(pip + [\'torch==2.3.1\', \'torchvision==0.18.1\', \'--index-url\', \'https://download.pytorch.org/whl/cu121\'], \'Installing VGGT GPU libraries\')\n            checked(pip + [\'numpy==2.2.6\', \'safetensors\', \'-r\', SOURCE / \'requirements.txt\'], \'Installing evaluation dependencies\')\n            pinned_repository(\'https://github.com/facebookresearch/vggt.git\', vggt_dir, vggt_revision)\n            checked(pip + [\'--no-deps\', \'-e\', vggt_dir], \'Installing VGGT\')\n        if not sam_ready:\n            if not SAM_PY.exists():\n                checked(uv + [\'venv\', \'--python\', \'3.12\', SAM_PY.parent.parent], \'Creating SAM 3 environment\')\n            pip = uv + [\'pip\', \'install\', \'--python\', SAM_PY]\n            checked(pip + [\'setuptools<81\', \'wheel\'], \'Installing SAM build dependencies\')\n            checked(pip + [\'torch==2.7.0\', \'torchvision==0.22.0\', \'--index-url\', \'https://download.pytorch.org/whl/cu126\'], \'Installing SAM GPU libraries\')\n            pinned_repository(\'https://github.com/facebookresearch/sam3.git\', sam_dir, sam_revision)\n            checked(pip + [\'-e\', sam_dir, \'einops\', \'psutil\', \'numpy<2\', \'pillow\', \'decord==0.6.0\', \'pycocotools\'], \'Installing SAM 3 dependencies\')\n    checked([EVAL_PY, \'-c\', eval_probe], \'Validating VGGT imports and GPU\')\n    checked([SAM_PY, \'-c\', sam_probe], \'Validating SAM imports and GPU\')\n    # Preserve actual package versions and include them in checkpoint identity.\n    for name, python in [(\'evaluation\', EVAL_PY), (\'sam\', SAM_PY)]:\n        versions_path = OUTPUT / (name+\'_packages.json\')\n        script = ("import importlib.metadata,json,pathlib; "\n                  f"pathlib.Path({str(versions_path)!r}).write_text(json.dumps(sorted((d.metadata[\'Name\'],d.version) for d in importlib.metadata.distributions())))")\n        bounded_run([python, \'-c\', script], OUTPUT / \'setup.log\', SOURCE, os.environ.copy(), DEADLINE)\n    print(f\'Environments ready. {(DEADLINE-time.monotonic())/60:.1f} minutes remain in this session.\')\nexcept Exception as exc:\n    write_json(OUTPUT / \'status.json\', {\'status\': \'setup_incomplete\', \'reason\': type(exc).__name__, \'num_views\': 50})\n    raise\n'
